import { RegionSession } from "./RegionSession.mjs";
import { concat, defer, EMPTY, merge, mergeAll, of, Subject, } from "rxjs";
import { RegionType } from "./protocol.mjs";
import { DEV } from "./debug.mjs";
import { orderPreservingId } from "./utils.mjs";
/**
 * Represents an active browser connection.
 */
export class Session {
    constructor(sessionId, pageInfo, user, params, initialUrl) {
        /**
         * We assign each region a unique id
         */
        this.nextRegionId = 0;
        this.subscription = null;
        /**
         * A map from region ids to their regions
         */
        this.regions = new Map();
        this.sidechannelSubject = new Subject();
        this.sidechannels = new Subject();
        this.createRegion = () => {
            const regionId = orderPreservingId("r", this.nextRegionId++);
            const region = new RegionSession(regionId, this.createRegion, (msg) => {
                this.sidechannelSubject.next(msg);
            }, this.initialUrl);
            this.regions.set(regionId, region);
            region.user = this.user;
            region.params = this.params;
            const removedNotification = defer(() => {
                this.regions.delete(regionId);
                return of({ type: "removed", regionId });
            });
            // when the region unmounts, it will complete its sidechannel, which we can
            // use for sending a removal event
            this.sidechannels.next(concat(region.sidechannel(), removedNotification));
            return region;
        };
        this.sessionId = sessionId;
        this.entrypoint = pageInfo;
        this.user = user && Object.freeze(Object.assign({}, user));
        this.params = params && Object.freeze(Object.assign({}, params));
        this.initialUrl = initialUrl;
    }
    static create(sessionId, page, user, params, initialUrl) {
        DEV `creating session ${sessionId} for ${page.path}`;
        return new Session(sessionId, page, user, params, initialUrl);
    }
    start(op, observer) {
        let root;
        const updatesRx = merge(
        // we need this to be listened to before instantiating any regions
        this.sidechannels.pipe(mergeAll()), this.sidechannelSubject, defer(() => {
            root = this.createRegion();
            return root.makeRenderLoop({
                refId: "",
                type: RegionType.Launched,
            });
        }), defer(() => {
            root.setRegionInput(this.entrypoint.code, undefined);
            return EMPTY;
        }));
        this.subscription = updatesRx.pipe(op).subscribe(observer);
    }
    stop() {
        const subscription = this.subscription;
        if (subscription) {
            this.subscription = null;
            subscription.unsubscribe();
        }
    }
    handleClientEvents(events) {
        // TODO: validate
        // we run through the events and the regions will report themselves as
        // needing to re-render
        events.forEach((event) => {
            // currently event.type is always "update"
            const { cSeq, updates } = event;
            updates.forEach(([regionId, update], i) => {
                const region = this.regions.get(regionId);
                if (!region) {
                    DEV `Unrecognized region ${regionId}`;
                    return;
                }
                region.handleConsumerUpdate(cSeq + i, update);
            });
        });
    }
}
